def line(id,x,y,w,h,color='#243247',width=4):
    o={'id':id,'type':'line','x':x,'y':y,'w':w,'h':h,'color':color,'strokeWidth':width}
    ops.append({'type':'create','shape':o})

def dashed(points,color,width=5,step=18,prefix='dash'):
    n=0
    for (x1,y1),(x2,y2) in zip(points,points[1:]):
        dx=x2-x1; dy=y2-y1
        dist=(dx*dx+dy*dy)**0.5
        if dist==0:
            continue
        ux=dx/dist; uy=dy/dist
        d=0
        on=True
        while d<dist:
            d2=min(d+step,dist)
            if on:
                line(f'{prefix}-{n}',x1+ux*d,y1+uy*d,(x1+ux*d2)-(x1+ux*d),(y1+uy*d2)-(y1+uy*d),color,width)
                n+=1

